def quote_bell_pricing(gross_cents: int = 990) -> dict:
    fee_cents = (gross_cents * 27) // 990
    return {
        'gross_cents': gross_cents,
        'platform_fee_cents': fee_cents,
        'net_after_fee_cents': gross_cents - fee_cents,
        'pricing_correlator_fourths': [4, 4, 4],
    }

def compute_bell_tax(pricing_out: dict) -> dict:
    gross = int(pricing_out['gross_cents'])
    fourths = list(pricing_out.get('pricing_correlator_fourths', [4, 4, 4]))
    return {
        'tax_reserve_cents': (gross * 90) // 990,
        'pricing_correlator_fourths': fourths,
        'tax_c11_fourth': -4,
    }

